bank=[]
def add(cat,topic,stem,options,key,explanation,tip='Baca kata kunci pertanyaan sebelum memilih jawaban.'):
 n=len(bank)+1
 bank.append(dict(code=f'CAT{n:03}',category=cat,topic=topic,stem=stem,options=[dict(id=chr(65+i),text=t,score=(key[i] if isinstance(key,list) else 5 if i==key else 0)) for i,t in enumerate(options)],explanation=explanation,tip=tip,source_type='original',review_status='editorial_draft'))
