for i,c in enumerate(cases):
 topic,stem,*rest=c
 opts=rest[:5]; reason=rest[5]
 # deterministic rotation; scores attached to option identity
 shift=(i*3+1)%5
 paired=list(zip(opts,[5,4,3,2,1]));paired=paired[shift:]+paired[:shift]
 add('TKP',topic,stem,[p[0] for p in paired],[p[1] for p in paired],reason,'Cari tindakan yang membantu, sesuai aturan, dan memiliki tindak lanjut. Bobot ini adalah penilaian latihan, bukan kunci resmi BKN.')
 for o in bank[-1]['options']:
  o['reason']=f"Bobot {o['score']}/5. "+{5:'Pilihan paling lengkap untuk kebutuhan kasus ini. '+reason,4:'Arah tindakan sudah tepat, tetapi tindak lanjutnya belum selengkap pilihan berbobot 5.',3:'Ada upaya membantu, tetapi belum menyelesaikan masalah utama secara memadai.',2:'Tindakan ini berisiko menunda penyelesaian atau mengabaikan tanggung jawab penting.',1:'Pilihan ini paling lemah karena mengabaikan kebutuhan, integritas, atau keselamatan dalam kasus ini.'}[o['score']]
assert len(bank)==110,len(bank)
(root/'bank-soal.json').write_text(json.dumps(bank,ensure_ascii=False,indent=2))
def sqlstr(x):return "'"+x.replace("'","''")+"'"
lines=['begin;']
for q in bank:lines.append('insert into cat_private.questions(code,payload) values ('+sqlstr(q['code'])+','+sqlstr(json.dumps(q,ensure_ascii=False))+'::jsonb) on conflict(code) do nothing;')
for id,title,mode,codes,official in [('latihan-100','Latihan lengkap · 100 soal','learn',bank[:100],False),('simulasi-110','Simulasi SKD · 110 soal','exam',bank,True),('twk-30','Fokus TWK · Kebangsaan','learn',bank[:30],False),('tiu-35','Fokus TIU · Logika & hitungan','learn',bank[30:65],False),('tkp-45','Fokus TKP · Situasi kerja','learn',bank[65:],False)]:
 lines.append('insert into cat_private.packages values ('+','.join([sqlstr(id),sqlstr(title),sqlstr(mode),'6000',"ARRAY["+','.join(sqlstr(q['code']) for q in codes)+"]",'true',str(official).lower()])+') on conflict(id) do nothing;')
lines.append('commit;');(root/'02-seed.sql').write_text('\n'.join(lines))
print('Bank:',len(bank),'soal; 30 TWK, 35 TIU, 45 TKP')
